// Compare every workflow file with the last scan. Only new or changed files are downloaded again.
const now = $now.toFormat('yyyy-MM-dd HH:mm');
const inventory = {};
for (const row of $('Load Inventory').all()) {
  if (row.json.key) inventory[row.json.key] = row.json;
}
const baseline = Object.keys(inventory).length === 0;
const repos = {};
for (const repo of $('Limit Repositories').all()) {
  if (repo.json.full_name) repos[repo.json.full_name] = repo.json;
}

const files = $input.all().filter(({ json }) => json.path && json.sha);
if (!files.length) return [{ json: { no_files: true } }];

return files.map(({ json: file }, index) => {
  const match = String(file.html_url || '').match(/github\.com\/([^/]+)\/([^/]+)\/blob\//);
  const owner = match ? match[1] : '';
  const name = match ? match[2] : '';
  const repo = `${owner}/${name}`;
  const key = `${repo}/${file.path}`;
  const previous = inventory[key];
  const changeType = !previous ? 'new' : previous.sha !== file.sha ? 'changed' : 'unchanged';
  const info = repos[repo] || {};
  let stored = {};
  try { stored = JSON.parse(previous?.details || '{}'); } catch (error) { stored = {}; }
  const unchanged = changeType === 'unchanged';
  return {
    json: {
      key, repo, owner, name, path: file.path, sha: file.sha, html_url: file.html_url,
      visibility: info.visibility || (info.private ? 'private' : 'public'),
      change_type: changeType,
      baseline,
      first_seen: previous?.first_seen || now,
      last_changed: unchanged ? (previous?.last_changed || now) : now,
      // Unchanged files keep the results of their last check
      findings: unchanged ? (stored.findings || []) : [],
      pins: unchanged ? (stored.pins || []) : [],
      ai_verdict: unchanged ? (previous?.ai_verdict || '') : '',
      ai_summary: unchanged ? (previous?.ai_summary || '') : '',
    },
    pairedItem: { item: index },
  };
});

// Static checks for the patterns used in recent GitHub Actions supply-chain attacks.
const meta = $('Changed?').item.json;
const settings = $('Settings').first().json;
const trusted = String(settings.trusted_action_owners || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);

if ($json.error || !$json.content) {
  return { json: { ...meta, fetch_error: String($json.error || 'Empty or unreadable file'), findings: [], pins: [], content: '' } };
}

const base64 = String($json.content).replace(/\s/g, '');
const text = typeof Buffer !== 'undefined'
  ? Buffer.from(base64, 'base64').toString('utf8')
  : decodeURIComponent(escape(atob(base64)));
const lines = text.split(/\r?\n/);
// Comments are ignored, so they can neither trigger nor hide a finding
const code = lines.map((l) => (/^\s*#/.test(l) ? '' : l.replace(/\s#.*$/, '')));
const codeText = code.join('\n');
const findings = [];
const pins = [];
const add = (rule, severity, line, title, fix) =>
  findings.push({ rule, severity, line, snippet: (lines[line - 1] || '').trim().slice(0, 160), title, fix });
const lineOf = (pattern) => {
  const index = code.findIndex((l) => pattern.test(l));
  return index >= 0 ? index + 1 : 1;
};

// Event fields an outside contributor can control
const UNTRUSTED = /\$\{\{[^}]*(github\.event\.(issue\.(title|body)|pull_request\.(title|body|head\.ref|head\.label|head\.repo\.default_branch)|comment\.body|review\.body|review_comment\.body|pages\.[^}]*page_name|commits\.[^}]*(message|author\.(email|name))|head_commit\.(message|author\.(email|name))|discussion\.(title|body)|workflow_run\.(head_branch|head_commit\.message))|github\.head_ref)[^}]*\}\}/;
// Services attackers use to collect stolen data
const EXFIL_HOSTS = /(webhook\.site|requestbin|pipedream\.net|ngrok|pastebin\.com|transfer\.sh|oast\.(fun|pro|live|site|online|me)|interact\.sh|burpcollaborator|hookbin|beeceptor|requestcatcher|discord(app)?\.com\/api\/webhooks|api\.telegram\.org\/bot)/i;
const NETWORK = /\b(curl|wget|nc|ncat|Invoke-WebRequest|Invoke-RestMethod|iwr|irm)\b/i;
const usesPullRequestTarget = /\bpull_request_target\b/.test(codeText);
const usesSelfHosted = /\bself-hosted\b/.test(codeText);
const discussionTrigger = /^\s*(-\s*)?discussion(_comment)?\s*:?\s*$/m.test(codeText) || /^\s*on\s*:.*\bdiscussion/m.test(codeText);
const hasPermissions = /^\s*permissions\s*:/m.test(codeText);

let blockIndent = -1; // indentation of the current multi-line run:/script: block, -1 when outside one
code.forEach((line, i) => {
  const n = i + 1;
  if (!line.trim()) return;
  const indent = line.match(/^\s*/)[0].length;
  if (blockIndent >= 0 && indent <= blockIndent) blockIndent = -1;
  let inScript = blockIndent >= 0;
  const scriptKey = line.match(/^(\s*)(-\s*)?(run|script)\s*:\s*(.*)$/);
  if (scriptKey) {
    const value = scriptKey[4].trim();
    if (value === '' || /^[|>][-+0-9]*$/.test(value)) {
      blockIndent = scriptKey[1].length + (scriptKey[2] || '').length;
      inScript = false;
    } else {
      inScript = true;
    }
  }

  const uses = line.match(/^\s*(?:-\s*)?uses\s*:\s*['"]?([^@\s'"]+)@([^\s'"]+)/);
  if (uses && !uses[1].startsWith('./') && !uses[1].startsWith('docker://')) {
    const [, action, ref] = uses;
    if (!/^[0-9a-f]{40}$/i.test(ref)) {
      const owner = action.split('/')[0].toLowerCase();
      const branchLike = !/\d/.test(ref);
      const severity = branchLike ? 'high' : trusted.includes(owner) ? 'low' : 'medium';
      add('unpinned-action', severity, n, `${action}@${ref} is not pinned to a commit SHA`,
        'Pin it to the full commit SHA from the suggestion and keep the version as a comment.');
      pins.push({ action, ref, line: n });
    }
  }
  if (inScript && UNTRUSTED.test(line)) {
    add('script-injection', 'high', n, 'Untrusted event data is inserted straight into a script',
      'Pass the value through an env variable and use it quoted, for example env: TITLE: ${{ github.event.issue.title }} and then "$TITLE".');
  }
  if (/toJSON\(\s*secrets\s*\)/i.test(line) || /\$\{\{\s*secrets\s*\}\}/.test(line)) {
    add('secrets-dump', 'critical', n, 'All repository secrets are dumped at once',
      'Remove it and reference only the individual secrets a step needs.');
  }
  if (NETWORK.test(line) && EXFIL_HOSTS.test(line)) {
    add('exfiltration-endpoint', /secrets\./.test(line) ? 'critical' : 'high', n, 'Sends data to a service commonly used to collect stolen data',
      'Treat this as a possible compromise: check who added it, remove it and rotate your secrets.');
  } else if (/secrets\./.test(line) && NETWORK.test(line)) {
    add('secret-in-network-call', 'low', n, 'A secret is used in a network command',
      'Confirm that the destination is a service you trust.');
  }
  if (/\b(curl|wget)\b[^|]*\|\s*(sudo\s+)?(ba|z)?sh\b/.test(line) || /\b(ba|z)?sh\s+<\(\s*(curl|wget)\b/.test(line) || /\biex\b.*\b(iwr|Invoke-WebRequest)\b/i.test(line)) {
    add('remote-script', 'medium', n, 'Downloads a script and runs it without verification',
      'Download it to a file, verify its checksum, then run it, or use a pinned action instead.');
  }
  if (/^\s*permissions\s*:\s*write-all\b/.test(line)) {
    add('broad-permissions', 'high', n, 'The GITHUB_TOKEN gets write access to everything',
      'Grant only what the job needs, for example permissions: contents: read.');
  }
  if (usesPullRequestTarget && /\bref\s*:/.test(line) && /github\.event\.pull_request\.head\.(sha|ref)|github\.head_ref|refs\/pull\//.test(line)) {
    add('pwn-request', 'critical', n, 'pull_request_target checks out untrusted pull request code',
      'Use the pull_request trigger instead, or never check out and run pull request code in this job.');
  }
});
if (usesPullRequestTarget && !findings.some((f) => f.rule === 'pwn-request')) {
  add('pull-request-target', 'medium', lineOf(/pull_request_target/), 'Uses pull_request_target, which runs with your secrets on pull requests from forks',
    'Make sure no step builds or runs code from the pull request.');
}
if (!hasPermissions) {
  add('default-permissions', 'low', 1, 'No permissions block, so the token uses the repository default, which can include write access',
    'Add permissions: contents: read at the top level and grant more per job only where needed.');
}
if (usesSelfHosted && meta.visibility === 'public') {
  add('self-hosted-public', 'high', lineOf(/\bself-hosted\b/), 'Self-hosted runner in a public repository',
    'Anyone who can open a pull request may be able to run code on this machine. Use GitHub-hosted runners for public repositories.');
}
if (usesSelfHosted && discussionTrigger) {
  add('runner-backdoor-pattern', 'critical', lineOf(/discussion/), 'Discussion-triggered job on a self-hosted runner, a known backdoor pattern (Shai-Hulud 2.0)',
    'Investigate now: check who added this file and whether the runner belongs to you.');
}

return { json: { ...meta, fetch_error: '', findings, pins, content: text.slice(0, 12000) } };

// Build one GitHub GraphQL query that resolves the commit SHA behind every unpinned action.
const unique = new Map();
for (const { json } of $input.all()) {
  for (const pin of json.pins || []) {
    const [owner, repo] = pin.action.split('/');
    if (owner && repo) unique.set(`${owner}/${repo}@${pin.ref}`, { owner, repo, ref: pin.ref });
  }
}
const refs = [...unique.entries()].slice(0, 60).map(([id, ref]) => ({ id, ...ref }));
const parts = refs.map((r, i) =>
  `r${i}: repository(owner: ${JSON.stringify(r.owner)}, name: ${JSON.stringify(r.repo)}) { object(expression: ${JSON.stringify(r.ref)}) { ... on Commit { oid } ... on Tag { target { ... on Commit { oid } } } } }`);
return [{ json: { refs, query: `query {\n${parts.join('\n') || 'viewer { login }'}\n}` } }];

// Add ready-to-paste pinned lines and pick which files get an AI review.
const settings = $('Settings').first().json;
const { refs } = $('Build Pin Query').first().json;
const data = $input.first().json.data || {};
const shaFor = {};
refs.forEach((ref, i) => {
  const found = data[`r${i}`]?.object;
  const oid = found?.oid || found?.target?.oid;
  if (oid) shaFor[ref.id] = oid;
});

const weight = { critical: 10, high: 5, medium: 2, low: 1 };
const riskOf = (file) => (file.findings || []).reduce((sum, f) => sum + (weight[f.severity] || 0), 0);
const files = $('Audit Rules').all().map(({ json }) => ({
  ...json,
  risk_score: riskOf(json),
  pins: (json.pins || []).map((pin) => {
    const [owner, repo] = pin.action.split('/');
    const sha = shaFor[`${owner}/${repo}@${pin.ref}`] || '';
    return { ...pin, sha, suggestion: sha ? `uses: ${pin.action}@${sha} # ${pin.ref}` : '' };
  }),
}));

// AI reviews only happen after the baseline run, for new or changed files, highest risk first
const maxReviews = Number(settings.max_ai_reviews) || 10;
const selected = new Set(files
  .filter((f) => !f.baseline && !f.fetch_error && f.change_type !== 'unchanged')
  .sort((a, b) => b.risk_score - a.risk_score)
  .slice(0, maxReviews)
  .map((f) => f.key));

return files.map((file) => ({ json: { ...file, ai_review: selected.has(file.key) } }));

// Combine the AI verdict with the file details and prepare the Slack alert text.
const file = $('Needs AI Review?').item.json;
const review = $json.output || {};
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const critical = (file.findings || []).filter((f) => f.severity === 'critical').length;
const label = review.verdict === 'malicious' ? '🚨 Malicious' : review.verdict === 'suspicious' ? '⚠️ Suspicious' : '🔴 High-risk';
const alertText = [
  `${label} workflow change in *${esc(file.repo)}*`,
  `File: <${file.html_url}|${esc(file.path)}> (${file.change_type})`,
  esc(review.summary),
  ...(review.evidence || []).slice(0, 5).map((e) => `• ${esc(e)}`),
  critical ? `Rule checks: ${critical} critical finding(s).` : '',
  `*Do now:* ${esc(review.recommended_action)}`,
].filter(Boolean).join('\n');

return {
  json: {
    record_type: 'verdict',
    key: file.key, repo: file.repo, path: file.path, html_url: file.html_url,
    verdict: review.verdict, confidence: review.confidence, summary: review.summary,
    evidence: review.evidence || [], recommended_action: review.recommended_action,
    critical, alert_text: alertText,
  },
};

// One row per workflow file for the gha_security_inventory Data Table.
const now = $now.toFormat('yyyy-MM-dd HH:mm');
const all = $input.all().map((item) => item.json);
const verdicts = {};
for (const v of all.filter((j) => j.record_type === 'verdict')) verdicts[v.key] = v;
const weight = { critical: 10, high: 5, medium: 2, low: 1 };

return all
  .filter((f) => f.record_type !== 'verdict' && f.change_type && f.key && !f.fetch_error)
  .map((f) => {
    const findings = f.findings || [];
    const count = (severity) => findings.filter((x) => x.severity === severity).length;
    const verdict = verdicts[f.key];
    let details = JSON.stringify({ findings, pins: f.pins || [] });
    if (details.length > 30000) details = JSON.stringify({ findings: findings.slice(0, 40), pins: (f.pins || []).slice(0, 40), truncated: true });
    return {
      json: {
        key: f.key, repo: f.repo, path: f.path, sha: f.sha, visibility: f.visibility,
        first_seen: f.first_seen, last_seen: now, last_changed: f.last_changed,
        risk_score: findings.reduce((sum, x) => sum + (weight[x.severity] || 0), 0),
        critical: count('critical'), high: count('high'), medium: count('medium'), low: count('low'),
        ai_verdict: verdict ? verdict.verdict : (f.ai_verdict || ''),
        ai_summary: verdict ? verdict.summary : (f.ai_summary || ''),
        details,
      },
    };
  });

// Summarise the whole scan for the AI brief and the Slack digest.
const all = $input.all().map((item) => item.json);
const files = all.filter((j) => j.record_type !== 'verdict' && j.change_type);
const verdicts = all.filter((j) => j.record_type === 'verdict');
const repositories = $('Limit Repositories').all().filter((r) => r.json.full_name).length;
const weight = { critical: 10, high: 5, medium: 2, low: 1 };
const severity = { critical: 0, high: 0, medium: 0, low: 0 };
const ruleCounts = {};
const byRepo = {};

for (const f of files) {
  const repo = (byRepo[f.repo] ||= { repo: f.repo, visibility: f.visibility, files: 0, risk: 0, critical: 0, high: 0 });
  repo.files += 1;
  for (const x of f.findings || []) {
    severity[x.severity] = (severity[x.severity] || 0) + 1;
    ruleCounts[x.rule] = (ruleCounts[x.rule] || 0) + 1;
    repo.risk += weight[x.severity] || 0;
    if (x.severity === 'critical') repo.critical += 1;
    if (x.severity === 'high') repo.high += 1;
  }
}

const baseline = files.length > 0 && files.every((f) => f.baseline);
const changed = files.filter((f) => !f.baseline && f.change_type !== 'unchanged');
const topFindings = files
  .flatMap((f) => (f.findings || [])
    .filter((x) => x.severity === 'critical' || x.severity === 'high')
    .map((x) => ({ repo: f.repo, path: f.path, url: f.html_url, ...x })))
  .sort((a, b) => weight[b.severity] - weight[a.severity])
  .slice(0, 25);
const verdictFor = (key) => verdicts.find((v) => v.key === key);

const findingsText = topFindings
  .map((t) => `- [${t.severity.toUpperCase()}] ${t.repo}/${t.path} line ${t.line}: ${t.title}`)
  .join('\n') || 'No critical or high findings.';
const changesText = changed
  .map((f) => {
    const v = verdictFor(f.key);
    return `- ${f.change_type.toUpperCase()}: ${f.repo}/${f.path}${v ? ` (AI verdict: ${v.verdict}. ${v.summary})` : ''}`;
  })
  .join('\n') || (baseline ? 'First run: baseline saved, change detection starts with the next run.' : 'No new or changed workflow files.');

return [{
  json: {
    date: $now.toFormat('yyyy-MM-dd'),
    baseline,
    stats: {
      repositories,
      repos_with_workflows: Object.keys(byRepo).length,
      workflow_files: files.length,
      new_files: files.filter((f) => f.change_type === 'new' && !f.baseline).length,
      changed_files: files.filter((f) => f.change_type === 'changed').length,
      ...severity,
      pinned_suggestions: files.reduce((sum, f) => sum + (f.pins || []).filter((p) => p.sha).length, 0),
      suspicious: verdicts.filter((v) => v.verdict === 'malicious' || v.verdict === 'suspicious').length,
    },
    rule_counts: ruleCounts,
    top_repos: Object.values(byRepo).filter((r) => r.risk > 0).sort((a, b) => b.risk - a.risk).slice(0, 8),
    top_findings: topFindings,
    findings_text: findingsText,
    changes_text: changesText,
  },
}];

