// Turn the scan report and the AI brief into one Slack message.
const report = $('Build Security Report').first().json;
const brief = $json.output || {};
const s = report.stats;
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = [
  `*🛡️ GitHub Actions security digest · ${report.date}*`,
  `*${esc(brief.headline)}*`,
  esc(brief.summary),
  `*Scan:* ${s.repositories} repos · ${s.workflow_files} workflow files · ${s.new_files} new · ${s.changed_files} changed${report.baseline ? ' (first run: baseline saved)' : ''}`,
  `*Findings:* 🔴 ${s.critical} critical · 🟠 ${s.high} high · 🟡 ${s.medium} medium · ⚪ ${s.low} low`,
];
const actions = (brief.priority_actions || []).slice(0, 5);
if (actions.length) {
  lines.push('*Priority actions*', ...actions.map((a, i) => `${i + 1}. *${esc(a.repo)}*: ${esc(a.action)} _(${esc(a.why)})_`));
}
if (brief.quick_win) lines.push(`*Quick win:* ${esc(brief.quick_win)}`);
if (report.top_repos.length) {
  lines.push('*Riskiest repositories*', ...report.top_repos.slice(0, 5).map((r) => `• ${esc(r.repo)} (${r.visibility}): ${r.critical} critical, ${r.high} high`));
}
if (s.suspicious) lines.push(`⚠️ ${s.suspicious} suspicious workflow change(s) were alerted separately.`);
lines.push(`_${s.pinned_suggestions} pinned SHA suggestions and full details are in the gha_security_inventory Data Table._`);
return [{ json: { slack_text: lines.filter(Boolean).join('\n') } }];

// Draft one GitHub issue per private repository with new serious findings (only when enabled).
const settings = $('Settings').first().json;
if (!settings.create_github_issues) return [];
const all = $input.all().map((item) => item.json);
const verdicts = {};
for (const v of all.filter((j) => j.record_type === 'verdict')) verdicts[v.key] = v;
// AI text can be influenced by a malicious workflow file, so it is neutralised before it goes into Markdown:
// no HTML, no links or images, no @mentions
const safe = (value) => String(value ?? '').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[\[\]]/g, '\\$&').replace(/@(?=\w)/g, '@\u200b');
const cell = (value) => safe(value).replace(/\|/g, '\\|').replace(/\n/g, ' ');
const byRepo = {};

for (const f of all.filter((j) => j.record_type !== 'verdict' && j.change_type && j.change_type !== 'unchanged' && j.visibility === 'private')) {
  const serious = (f.findings || []).filter((x) => x.severity === 'critical' || x.severity === 'high');
  const verdict = verdicts[f.key];
  const flagged = verdict && (verdict.verdict === 'malicious' || verdict.verdict === 'suspicious');
  if (!serious.length && !flagged) continue;
  (byRepo[f.repo] ||= { owner: f.owner, name: f.name, files: [] }).files.push({ f, serious, verdict });
}

return Object.values(byRepo).map((repo) => {
  const sections = repo.files.map(({ f, serious, verdict }) => {
    const rows = serious.map((x) => `| ${x.severity} | ${x.line} | ${cell(x.title)} | ${cell(x.fix)} |`).join('\n');
    const pins = (f.pins || []).filter((p) => p.suggestion).map((p) => `- Line ${p.line}: \`${p.suggestion}\``).join('\n');
    return [
      `### [${f.path}](${f.html_url})`,
      verdict ? `**AI review:** ${safe(verdict.verdict)} (${safe(verdict.confidence)} confidence). ${safe(verdict.summary)}` : '',
      rows ? `| Severity | Line | Finding | Fix |\n|---|---|---|---|\n${rows}` : '',
      pins ? `**Pinned versions to paste:**\n${pins}` : '',
    ].filter(Boolean).join('\n\n');
  });
  return {
    json: {
      owner: repo.owner,
      name: repo.name,
      title: `GitHub Actions security: ${repo.files.length} workflow file(s) need attention`,
      body: [`Opened by the GitHub Actions Security Guard n8n workflow on ${$now.toFormat('yyyy-MM-dd')}.`, ...sections].join('\n\n'),
    },
  };
});
